// --- Fractions ---
V34("fracrep",
  () => { let a, b, c, d, x, y; do { b = R.int(2, 5); x = R.int(1, 4); a = x * b + R.int(1, b - 1); d = R.int(2, 5); y = x + R.int(2, 4); c = y * d + R.int(1, d - 1); } while (a === c || b === d || [a, b, c, d].includes(y - x)); return QV("Combien de nombres entiers sont strictement compris entre " + M("\\frac{" + a + "}{" + b + "}") + " et " + M("\\frac{" + c + "}{" + d + "}") + " ?", y - x, M(x + " < \\frac{" + a + "}{" + b + "} < " + (x + 1)) + " et " + M(y + " < \\frac{" + c + "}{" + d + "} < " + (y + 1)) + " : les entiers de " + (x + 1) + " à " + y + ", soit " + (y - x) + ".", { guide: [GS("Entier juste en dessous de " + M("\\frac{" + a + "}{" + b + "}") + " (quotient de " + a + " : " + b + ") ?", x, M(x + " < \\frac{" + a + "}{" + b + "} < " + (x + 1)) + "."), GS("Entier juste en dessous de " + M("\\frac{" + c + "}{" + d + "}") + " ?", y, M(y + " < \\frac{" + c + "}{" + d + "} < " + (y + 1)) + "."), GS("Entiers strictement compris : de " + (x + 1) + " à " + y + ". Combien ?", y - x, (y - x) + " entiers.")], traps: [TRAP(y - x + 1, "Strictement compris : les entiers sont " + (x + 1) + " à " + y + "."), TRAP(y - x - 1, "Situe chaque fraction entre deux entiers : " + x + " < … et … < " + (y + 1) + ".")] }); },
  () => { let a, b; do { b = R.int(3, 9); a = R.int(2 * b + 1, 9 * b); } while (a % b === 0); return QV("La fraction " + M("\\frac{" + a + "}{" + b + "}") + " est comprise entre deux entiers consécutifs. Quel est le plus grand des deux ?", Math.ceil(a / b), M(a + " = " + Math.floor(a / b) + " \\cdot " + b + " + " + (a % b)) + ", donc " + M(Math.floor(a / b) + " < \\frac{" + a + "}{" + b + "} < " + Math.ceil(a / b)) + ".", { guide: [GS("Quotient de la division entière " + a + " : " + b + " ?", Math.floor(a / b), M(a + " = " + Math.floor(a / b) + " \\cdot " + b + " + " + (a % b)) + "."), GS("Le plus grand des deux entiers (quotient + 1) ?", Math.ceil(a / b), M(Math.ceil(a / b)) + ".")], traps: [TRAP(Math.floor(a / b), "C'est le plus petit des deux."), TRAP(a % b, "C'est le reste ; le plus grand entier est le quotient + 1.")] }); },
);
const irr = (lo, hi) => { let a, b; do { b = R.int(lo, hi); a = R.int(2, b - 1); } while (gcd(a, b) !== 1); return [a, b]; };
V("fracsimp", 1,
  () => { const [a, b] = irr(3, 9), k = R.int(3, 8); return QV("Complète : " + M("\\frac{" + a + "}{" + b + "} = \\frac{" + a * k + "}{?}"), b * k, "On a multiplié le numérateur par " + k + " : " + M(b + " \\cdot " + k + " = " + b * k) + ".", { guide: [GS("Par combien a-t-on multiplié le numérateur ? " + M(a * k + " : " + a), k, M(a * k + " : " + a + " = " + k) + "."), GS("On multiplie aussi le dénominateur : " + M(b + " \\cdot " + k) + " = ?", b * k, M(b * k) + ".")], traps: [TRAP(b + a * k - a, "Amplifier, c'est multiplier (pas ajouter) : le dénominateur aussi est multiplié par " + k + "."), TRAP(a * k * k, "On multiplie le dénominateur par " + k + ", comme le numérateur.")] }); },
  () => { const [a, b] = irr(3, 9), k = R.int(3, 12); return QV("Par quel nombre a-t-on amplifié " + M("\\frac{" + a + "}{" + b + "}") + " pour obtenir " + M("\\frac{" + a * k + "}{" + b * k + "}") + " ?", k, M(b * k + " : " + b + " = " + k) + ".", { guide: [GS("Le dénominateur " + b + " est devenu " + b * k + ". Facteur : " + M(b * k + " : " + b) + " = ?", k, M(k) + " (vérifie : " + M(a + " \\cdot " + k + " = " + a * k) + ").")], traps: [TRAP(b * k - b, "Amplifier, c'est multiplier : on cherche le facteur, " + b * k + " : " + b + "."), TRAP(a * k, "On cherche le facteur d'amplification, pas le nouveau numérateur.")] }); },
);
