VA("probeq", 2, () => { const l = R.int(3, 12), k = R.int(2, 4); return QV("La longueur d'un rectangle vaut " + (k === 2 ? "le double" : k === 3 ? "le triple" : "le quadruple") + " de sa largeur. Son périmètre vaut " + 2 * (l + k * l) + " cm. Quelle est sa largeur (en cm) ?", l, M("2(l + " + k + "l) = " + 2 * (l + k * l) + " \\iff " + 2 * (k + 1) + "l = " + 2 * (l + k * l) + " \\iff l = " + l) + " cm."); });
