VA("volcone", 2, () => { const r = R.pick([3, 6]), v = (4 * r ** 3) / 3; return QV("Une boule a un volume de " + M(v + "\\pi") + " cm³. Quel est son rayon (en cm) ?", r, M("\\frac{4}{3}\\pi r^3 = " + v + "\\pi \\iff r^3 = " + r ** 3 + " \\iff r = " + r) + " cm."); });
VA("volcone", 3, () => { const r = R.int(2, 6), h = R.int(1, 4) * 3; return QV("Un cône de hauteur " + h + " cm a un volume de " + M((r * r * h) / 3 + "\\pi") + " cm³. Quel est son rayon (en cm) ?", r, M("\\frac{1}{3}\\pi r^2 \\cdot " + h + " = " + (r * r * h) / 3 + "\\pi \\iff r^2 = " + r * r) + ", " + M("r = " + r) + " cm."); });
