VA("parenth", 2, () => { const a = R.int(3, 9), b = R.int(2, 6), c = R.int(2, 9); return Object.assign(QX("Supprime les parenthèses et réduis : " + M(a + " - (2x - " + b + ") - (" + c + " - x)"), a + "-(2x-" + b + ")-(" + c + "-x)", M(a + " - 2x + " + b + " - " + c + " + x = -x + " + (a + b - c)), { form: "expanded" }), { canon: "-x+" + (a + b - c) }); });
