VA("interpar", 3, () => { const p = R.int(2, 5), q = R.int(1, 4); if (p === q) return VAR.interpar[3][0](); return QV("La parabole " + M("y = x^2") + " et la droite " + M("y = " + (p - q) + "x + " + p * q).replace("1x", "x") + " se coupent en deux points. Quelle est l'abscisse du point le plus à droite ?", p, M("x^2 - " + (p - q) + "x - " + p * q + " = (x - " + p + ")(x + " + q + ") = 0") + " : " + M("x = " + p) + " ou " + M("x = -" + q) + "."); });
VA("exactes", 3, () => { const d = R.int(2, 10) * 2; return QV("Calcule l'aire d'un carré dont la diagonale mesure " + d + " cm (en cm²).", (d * d) / 2, "Côté " + M("\\frac{" + d + "}{\\sqrt{2}}") + " ; aire " + M("\\frac{" + d + "^2}{2} = " + (d * d) / 2) + " cm²."); });
VA("trigexact", 1, () => { const h = R.int(2, 8) * 2; return QV("Dans un triangle rectangle, l'hypoténuse mesure " + h + " cm et un angle aigu 60°. Combien mesure le côté opposé à cet angle (valeur exacte, en cm) ?", (h / 2) * Math.sqrt(3), M(h + " \\cdot \\sin 60° = " + h + " \\cdot \\frac{\\sqrt{3}}{2} = " + h / 2 + "\\sqrt{3}") + " cm."); });
VA("trigexact", 2, () => { const L = R.int(2, 8); return QV("Une échelle de " + L + " m fait un angle de 45° avec le sol. À quelle hauteur touche-t-elle le mur (valeur exacte, en m) ?", (L * Math.SQRT2) / 2, M(L + " \\cdot \\sin 45° = " + L + " \\cdot \\frac{\\sqrt{2}}{2}" + (L % 2 === 0 ? " = " + L / 2 + "\\sqrt{2}" : "")) + " m."); });
VA("trigexact", 3, () => { const h = R.int(5, 25), d = R.pick([100, 200]); return QV("Une route monte de " + h + " m sur " + d + " m de distance horizontale. Quel angle fait-elle avec l'horizontale, en degrés ? Arrondis au dixième.", Math.atan(h / d) / DEG, M("\\tan \\alpha = \\frac{" + h + "}{" + d + "}") + ", " + M("\\alpha \\approx " + dec(+(Math.atan(h / d) / DEG).toFixed(1)) + "°") + ".", { round: 0.1 }); });
VA("valint", 1, () => { const k = R.int(2, 5), a = R.int(1, 6); return QSet("Quelle est la valeur interdite de " + M("\\frac{5}{" + k + "x - " + k * a + "}") + " ?", [a], M(k + "x - " + k * a + " = 0 \\iff x = " + a) + "."); });
VA("valint", 3, () => { const a = R.int(2, 9), k = R.int(1, 5); return QSet("Quelles sont les valeurs interdites de " + M("\\frac{" + k + "}{x^2 + " + a + "x}") + " ? Sépare-les par « ; ».", [0, -a], M("x(x + " + a + ") = 0") + " : " + M("x = 0") + " et " + M("x = -" + a) + "."); });
VA("homogrec", 1, () => { const a = R.int(2, 9), b = R.int(1, 6); return QX("Soit " + M("f(x) = \\frac{" + a + "}{x} + " + b) + ". Donne l'expression de " + M("f^{-1}(x)") + ".", a + "/(x-" + b + ")", M("y = \\frac{" + a + "}{x} + " + b + " \\iff x = \\frac{" + a + "}{y - " + b + "}") + ", donc " + M("f^{-1}(x) = \\frac{" + a + "}{x - " + b + "}") + ".", { guide: [GS("On pose " + M("y = \\frac{" + a + "}{x} + " + b) + " : " + M("x = \\frac{" + a + "}{y - ?}") + " : quel nombre ?", b, M("x = \\frac{" + a + "}{y - " + b + "}") + "."), { ask: "Expression de " + M("f^{-1}(x)") + " ?", spec: { kind: "expr", expr: a + "/(x-" + b + ")" }, sol: M("f^{-1}(x) = \\frac{" + a + "}{x - " + b + "}") + "." }] }); });
VA("expo", 2, () => { const n = R.int(2, 3); return QV("Résous : " + M("3^{2x} = " + mille(3 ** (2 * n))), n, M(mille(3 ** (2 * n)) + " = 3^{" + 2 * n + "}") + ", donc " + M("2x = " + 2 * n) + " et " + M("x = " + n) + ".", { traps: [TRAP(2 * n, "C'est la valeur de " + M("2x") + ". Il reste à diviser par 2.")], guide: [GS(M(mille(3 ** (2 * n))) + " = " + M("3^{?}") + " : exposant ?", 2 * n, M("3^{" + 2 * n + "}") + "."), GS("2x = " + 2 * n + " : x = ?", n, M("x = " + n) + ".")] }); });
VA("expfrac", 1, () => { const [b, q, p] = R.pick([[81, 4, 3], [8, 3, 2], [32, 5, 2], [16, 4, 3]]); const r = Math.round(b ** (1 / q)); return QV("Calcule " + M("\\left(\\sqrt[" + q + "]{" + b + "}\\right)^{" + p + "}"), r ** p, M("\\sqrt[" + q + "]{" + b + "} = " + r) + ", puis " + M(r + "^{" + p + "} = " + r ** p) + ".", { traps: [TRAP(r, "C'est la racine. Il reste à l'élever à la puissance " + p + ".")], guide: [GS(M("\\sqrt[" + q + "]{" + b + "}") + " = ?", r, M(r) + "."), GS(M(r + "^{" + p + "}") + " = ?", r ** p, M(r ** p) + ".")] }); });
VA("expfrac", 2, () => { const [b, q] = R.pick([[1000, 3], [100, 2], [10000, 4]]); return QV("Calcule " + M(mille(b) + "^{-\\frac{1}{" + q + "}}") + " (nombre décimal).", 0.1, M("\\frac{1}{\\sqrt[" + q + "]{" + mille(b) + "}} = \\frac{1}{10} = 0{,}1") + ".", { traps: [TRAP(-10, "Un exposant négatif ne rend pas le nombre négatif : il donne l'inverse."), TRAP(10, "C'est la racine. L'exposant négatif demande encore l'inverse.")], guide: [GS(M("\\sqrt[" + q + "]{" + mille(b) + "}") + " = ?", 10, "10."), GS("Inverse de 10 (nombre décimal) ?", 0.1, M("0{,}1") + ".")] }); });
VA("decomp", 1, () => { const a = R.int(2, 5), b = R.int(1, 7), n = R.int(2, 4); return QX("On écrit " + M("h(x) = (" + a + "x + " + b + ")^{" + n + "}") + " sous la forme " + M("h(x) = f(g(x))") + " avec " + M("f(x) = x^{" + n + "}") + ". Donne g(x).", a + "x+" + b, M("g(x) = " + a + "x + " + b), { guide: [GS("Contenu de la parenthèse : coefficient de x ?", a, M(a) + "."), { ask: "Réponse (expression) ?", spec: { kind: "expr", expr: a + "x+" + b }, sol: M("g(x) = " + a + "x + " + b) + "." }] }); });
VA("log", 1, () => { const n = R.int(2, 4); return QV("Calcule " + M("\\log 0{,}" + "0".repeat(n - 1) + "1") + ".", -n, M("0{,}" + "0".repeat(n - 1) + "1 = 10^{-" + n + "}") + ", donc " + M("-" + n) + ".", { traps: [TRAP(n, "Attention au signe : le nombre est plus petit que 1, son logarithme est négatif."), TRAP(-(n - 1), "Compte bien les rangs : le 1 est au rang " + n + " après la virgule.")], guide: [GS(M("0{,}" + "0".repeat(n - 1) + "1 = 10^{?}") + " : exposant ?", -n, M(-n) + ".")] }); });
VA("log", 2, () => { const c = R.pick([5, 7, 12, 20]); return Object.assign(QE("Résous " + M("e^x = " + c) + " (valeur exacte avec ln, ou au centième).", Math.log(c), M("x = \\ln " + c + " \\approx " + dec(r2(Math.log(c)))), 0.01, [TRAP(c / Math.E, "On ne divise pas par e : on prend le logarithme naturel des deux membres."), TRAP(Math.log10(c), "C'est " + M("\\log " + c) + " (base 10). Avec la base e, on utilise ln.")]), { guide: [GS("x = ln " + c + " (au centième) ?", Math.log(c), M(dec(r2(Math.log(c)))) + ".", 0.01)] }); });
VA("log", 3, () => { const [a, b, v] = R.pick([[40, 5, 3], [48, 3, 4], [96, 3, 5], [20, 5, 2], [80, 5, 4]]); return QV("Calcule sans calculatrice : " + M("\\log_2 " + a + " - \\log_2 " + b) + ".", v, M("\\log_2 \\frac{" + a + "}{" + b + "} = \\log_2 " + a / b + " = " + v) + ".", { traps: [TRAP(Math.log2(a - b), "Attention : " + M("\\log_2 a - \\log_2 b = \\log_2 \\frac{a}{b}") + ", pas " + M("\\log_2(a - b)") + "."), TRAP(a / b, "C'est le quotient. Il reste à prendre son logarithme en base 2.")], guide: [GS("Différence de log = log du quotient : " + M(a + " : " + b) + " = ?", a / b, M(a / b) + "."), GS(M("\\log_2 " + a / b) + " = ?", v, M(v) + ".")] }); });
VA("logbase", 1, () => { const [b, x, v] = R.pick([[27, 3, 1 / 3], [16, 2, 1 / 4], [25, 125, 1.5], [4, 8, 1.5], [8, 16, 4 / 3]]); return QV("Quel exposant x vérifie " + M(b + "^x = " + x) + " ?", v, M("x = \\log_{" + b + "} " + x + " = " + frac(Math.round(v * 12), 12)) + ".", { traps: [TRAP(1 / v, "Tu as inversé le quotient des exposants : " + M("x = \\log_{" + b + "} " + x) + ".")], guide: [GS("x = " + M("\\log_{" + b + "} " + x) + " : écris les deux nombres comme puissances d'une même base, puis divise les exposants. x = ?", v, M(frac(Math.round(v * 12), 12)) + ".")] }); });
VA("logbase", 3, () => { const n = R.int(3, 5); return QV("Calcule " + M("\\log_2 3 \\cdot \\log_3 4 \\cdot \\log_4 " + 2 ** n) + " (valeur exacte).", n, "Les ln intermédiaires se simplifient : " + M("\\frac{\\ln " + 2 ** n + "}{\\ln 2} = " + n) + ".", { traps: [TRAP(2 ** n, "Le logarithme est un exposant : à quelle puissance faut-il élever 2 pour obtenir " + 2 ** n + " ?")], guide: [GS("Changement de base : tous les ln intermédiaires se simplifient. Il reste " + M("\\log_2 " + 2 ** n) + " = ?", n, M(n) + ".")] }); });
VA("trigcercle", 2, () => { const [v, s, a] = R.pick([[0.5, "\\frac{1}{2}", 150], [Math.SQRT1_2, "\\frac{\\sqrt{2}}{2}", 135], [Math.sqrt(3) / 2, "\\frac{\\sqrt{3}}{2}", 120]]); return QV("Pour quel angle " + M("\\alpha") + " compris entre 90° et 180° a-t-on " + M("\\sin\\alpha = " + s) + " (en degrés) ?", a, "L'angle aigu associé est " + (180 - a) + "° ; dans le 2e quadrant : " + M("180° - " + (180 - a) + "° = " + a + "°") + "."); });
VA("trigcercle", 3, () => { const [t, s, a] = R.pick([[1, "1", 225], [Math.sqrt(3), "\\sqrt{3}", 240], [1 / Math.sqrt(3), "\\frac{\\sqrt{3}}{3}", 210]]); return QV("Quel angle " + M("\\alpha") + " compris entre 180° et 270° vérifie " + M("\\tan\\alpha = " + s) + " (en degrés) ?", a, "Angle aigu associé " + (a - 180) + "° ; 3e quadrant : " + M("180° + " + (a - 180) + "° = " + a + "°") + "."); });
VA("eqparam", 3, () => { const b = R.pick([4, 6, 8, 12]), c = R.pick([1, 2, 4]); const m = (b * b) / (4 * c); if (!Number.isInteger(m) || m < 2) return VAR.eqparam[3][0](); return QV("Pour quelle valeur de m l'équation " + M("mx^2 + " + b + "x + " + c + " = 0") + " a-t-elle une solution double ?", m, M("\\Delta = " + b * b + " - 4 \\cdot m \\cdot " + c + " = 0 \\iff m = " + m) + "."); });
VA("statfreq", 2, () => clean(() => { const e = [R.int(2, 9), R.int(2, 9), R.int(2, 9), R.int(2, 9)], k = R.int(2, 3); const c = e.slice(0, k).reduce((a, b) => a + b, 0); return QV("Notes d'un test (sur 6) : " + e[0] + " élèves ont 3, " + e[1] + " ont 4, " + e[2] + " ont 5 et " + e[3] + " ont 6. Combien d'élèves ont une note inférieure ou égale à " + (k + 2) + " (effectif cumulé) ?", c, e.slice(0, k).join(" + ") + " = " + c + "."); }));
VA("stats", 2, () => { const a = R.int(1, 4), b = R.int(5, 8), x = R.int(9, 12), y = R.int(14, 17), c = R.int(18, 22), d = R.int(23, 28); const m = (x + y) / 2; if (!Number.isInteger(m)) return VAR.stats[2][0](); return QV("Série triée de 6 valeurs : " + a + "   " + b + "   x   " + y + "   " + c + "   " + d + ". Sa médiane vaut " + m + ". Que vaut x ?", x, M("\\frac{x + " + y + "}{2} = " + m) + ", donc " + M("x = " + x) + "."); });
VA("domaine", 2,
  () => { const a = R.int(1, 9); return { q: "Détermine le domaine de définition de " + M("f(x) = \\frac{1}{\\sqrt{x - " + a + "}}") + ".", spec: { kind: "solset", ivs: [[a, false, Infinity, false]] }, sol: "Sous la racine : " + M("x - " + a + " \\ge 0") + ", et la racine ne doit pas être nulle (dénominateur) : " + M("x > " + a) + ", soit " + M("]" + a + " \\,;\\, +\\infty[") + "." }; },
  () => { const a = R.int(1, 9); return { q: "Détermine le domaine de définition de " + M("f(x) = \\frac{\\sqrt{x}}{x - " + a + "}") + ".", spec: { kind: "solset", ivs: [[0, true, a, false], [a, false, Infinity, false]] }, sol: M("x \\ge 0") + " (racine) et " + M("x \\ne " + a) + " (dénominateur) : " + M("[0 \\,;\\, " + a + "[ \\cup ]" + a + " \\,;\\, +\\infty[") + "." }; },
);

// ======================= « Trouve l'erreur » (24.11, chantier I, suite) =======================
// Un camarade a fait une faute typique ; l'élève la repère et donne le bon résultat (ctx "erreur", piège = le résultat
// faux du camarade). Liste et erreurs visées : tools/trouve_erreur.md.
(function () {
  const who = () => R.pick(["Sam", "Lina", "Noé", "Inès", "Yanis", "Léa"]);
  const nT = (v) => { const [i, f] = String(r6(v)).split("."); return (i.replace("-", "").length >= 4 ? i.replace(/\B(?=(\d{3})+(?!\d))/g, "\\text{'}") : i) + (f ? "{,}" + f : ""); };
  const r2 = (v) => Math.round(v * 100) / 100;
  // pow9 : la puissance passe avant la multiplication.
  VA("pow9", 2, () => { const a = R.int(2, 5), b = R.int(3, 9), v = a * b * b, f = (a * b) ** 2, w = who();
    return QV(w + " écrit : « " + M(a + " \\cdot " + b + "^2 = " + a * b + "^2 = " + f) + " ». Trouve l'erreur, puis calcule correctement " + M(a + " \\cdot " + b + "^2") + ".", v,
      "Erreur : la puissance passe <b>avant</b> la multiplication ; l'exposant 2 ne porte que sur " + M(b) + ". " + M(a + " \\cdot " + b + "^2 = " + a + " \\cdot " + b * b + " = " + v) + ".",
      { ctx: "erreur", guide: [GS("D'abord la puissance : " + M(b + "^2") + " = ?", b * b, M(b * b) + "."), GS("Puis " + M(a + " \\cdot " + b * b) + " = ?", v, M(v) + ".")],
        traps: [TRAP(f, "C'est le résultat de " + w + " : il a multiplié avant d'élever au carré ; ce serait " + M("(" + a + " \\cdot " + b + ")^2") + ".")] }); });
  // aire1 : aire du triangle sans la division par 2.
  VA("aire1", 2, () => clean(() => { const b = R.int(4, 15), h = R.int(3, 12), v = r6((b * h) / 2), w = who(), c = R.pick(["d'un triangle", "d'une voile triangulaire", "d'un fanion triangulaire"]);
    return QV("La base " + c + " mesure " + M(b) + " cm et la hauteur correspondante " + M(h) + " cm. " + w + " calcule l'aire : « " + M(b + " \\cdot " + h + " = " + b * h) + " cm² ». Trouve l'erreur, puis donne l'aire (en cm²).", v,
      "Erreur : " + M(b + " \\cdot " + h) + " est l'aire du <b>rectangle</b> de mêmes dimensions ; le triangle en occupe la moitié. " + M("A = \\frac{" + b + " \\cdot " + h + "}{2} = " + dec(v)) + " cm².",
      { ctx: "erreur", guide: [GS("Aire du rectangle de mêmes base et hauteur ?", b * h, M(b * h) + " cm²."), GS("Le triangle en est la moitié : aire ?", v, M(b * h + " : 2 = " + dec(v)) + " cm².")],
        traps: [TRAP(b * h, "C'est le résultat de " + w + " : il manque la division par 2."), TRAP(b + h, "L'aire est un produit, divisé par 2.")] }); }));
  // fractout : fraction d'une quantité, division et multiplication inversées.
  VA("fractout", 2, () => { const [a, b] = R.pick([[2, 3], [3, 4], [2, 5], [3, 5], [5, 6], [3, 8], [5, 8], [4, 5]]), m = R.int(2, 9), N = a * b * m, v = (N * a) / b, f = (N * b) / a, w = who(),
      c = R.pick([["Un livre a " + N + " pages. Lina en a lu les", "pages lues"], ["Un trajet fait " + N + " km. On en a parcouru les", "km parcourus"], ["Une cagnotte contient " + N + " CHF. On en dépense les", "CHF dépensés"]]);
    return QV(c[0] + " " + M("\\frac{" + a + "}{" + b + "}") + ". " + w + " calcule : « " + M(N + " : " + a + " \\cdot " + b + " = " + f) + " ». Trouve l'erreur, puis donne le bon nombre de " + c[1] + ".", v,
      "Erreur : " + w + " a inversé les rôles. Le dénominateur " + M(b) + " dit en combien de parts on partage, le numérateur " + M(a) + " combien de parts on prend : " + M(N + " : " + b + " \\cdot " + a + " = " + v) + ". (Une fraction plus petite que 1 donne moins que " + N + ".)",
      { ctx: "erreur", guide: [GS("Une part : " + M(N + " : " + b) + " = ?", N / b, M(N / b) + "."), GS(a + " parts : " + M(N / b + " \\cdot " + a) + " = ?", v, M(v) + ".")],
        traps: [TRAP(f, "C'est le résultat de " + w + " : on divise par le dénominateur " + b + " et on multiplie par le numérateur " + a + "."), TRAP(N / b, "Ça, c'est une seule part ; il en faut " + a + ".")] }); });
  // dec10 : « on ajoute des zéros » après la virgule.
  VA("dec10", 2, () => { const z = R.int(1, 3), k = 10 ** z, d = R.pick([1, 2]); let x; do x = R.int(11, 99 * 10 ** (d - 1) + 9) / 10 ** d; while (Math.round(x * 10 ** d) % 10 === 0); x = r6(x);
    const v = r6(x * k), w = who();
    return QV(w + " écrit : « " + M((k >= 1000 ? nT(k) + " \\cdot " + dec(x) : dec(x) + " \\cdot " + k) + " = " + dec(x) + "0".repeat(z)) + " ». Trouve l'erreur, puis donne le bon résultat.", v,
      "Erreur : ajouter des zéros <b>après la virgule</b> ne change pas le nombre (" + M(dec(x) + "0".repeat(z) + " = " + dec(x)) + "). Multiplier par " + M(nT(k)) + ", c'est déplacer la virgule de " + z + " rang" + (z > 1 ? "s" : "") + " vers la droite : " + M(nT(v)) + ".",
      { plain: true, ctx: "erreur", guide: [GS("De combien de rangs la virgule se déplace-t-elle vers la droite ?", z, z + " rang" + (z > 1 ? "s" : "") + " (autant que de zéros dans " + nT(k).replace("\\text{'}", "'") + ")."), GS("Résultat ?", v, M(nT(v)) + ".")],
        traps: [TRAP(x, "C'est le nombre de " + w + " : il vaut toujours " + dec(x).replace("{,}", ",") + ", il n'a pas été multiplié."), TRAP(r6(x * 10 ** (z + 1)), "Un rang par zéro de " + k + ".")] }); });
  // uaire : conversion d'aire avec le facteur des longueurs. La forme d'origine est remise dans la liste pour que l'erreur reste une forme parmi d'autres.
  VA("uaire", 2, () => GEN.uaire(2), () => { const [u1, u2, f] = R.pick([["m", "cm", 100], ["dm", "mm", 100], ["km", "m", 1000], ["m", "dm", 10], ["cm", "mm", 10], ["dm", "cm", 10]]), x = R.int(12, 95) / 10, v = r6(x * f * f), faux = r6(x * f), w = who();
    return QV(w + " convertit " + M(dec(x) + tu(u1 + "^2")) + " en " + u2 + "² : « " + M("1" + tu(u1) + " = " + nT(f) + tu(u2)) + ", donc " + M(dec(x) + tu(u1 + "^2") + " = " + nT(faux) + tu(u2 + "^2")) + " ». Trouve l'erreur, puis donne la bonne mesure en " + u2 + "².", v,
      "Erreur : un carré de 1 " + u1 + " de côté contient " + M(nT(f) + " \\cdot " + nT(f) + " = " + nT(f * f)) + " carrés de 1 " + u2 + " de côté. Pour les aires, le facteur est " + M(nT(f * f)) + " : " + M(dec(x) + " \\cdot " + nT(f * f) + " = " + nT(v)) + " " + u2 + "².",
      { plain: true, ctx: "erreur", guide: [GS("1 " + u1 + "² = combien de " + u2 + "² ? (" + nT(f).replace("\\text{'}", "'") + " · " + nT(f).replace("\\text{'}", "'") + ")", f * f, M("1" + tu(u1 + "^2") + " = " + nT(f * f) + tu(u2 + "^2")) + "."), GS(dec(x).replace("{,}", ",") + " " + u1 + "² en " + u2 + "² ?", v, M(nT(v) + tu(u2 + "^2")) + ".")],
        traps: [TRAP(faux, "C'est le résultat de " + w + " : " + nT(f).replace("\\text{'}", "'") + " est le facteur des longueurs ; pour les aires, c'est " + nT(f * f).replace(/\\text\{'\}/g, "'") + ".")] }); });
  // perim : périmètre confondu avec l'aire.
  VA("perim", 2, () => clean(() => { let L, l; do { L = R.int(5, 25); l = R.int(3, L - 1); } while ([L, l, L * l].includes(2 * (L + l))); const v = 2 * (L + l), w = who(), c = R.pick([["un jardin", "de clôture"], ["un terrain de jeu", "de barrière"], ["une nappe", "de ruban pour la border"]]);
    return QV("Pour " + c[0] + " rectangulaire de " + M(L) + " m sur " + M(l) + " m, " + w + " calcule la longueur " + c[1] + " : « " + M(L + " \\cdot " + l + " = " + L * l) + " m ». Trouve l'erreur, puis donne la bonne longueur (en m).", v,
      "Erreur : " + M(L + " \\cdot " + l) + " est l'<b>aire</b> (en m²), la surface. La clôture fait le tour : c'est le périmètre, " + M(L + " + " + l + " + " + L + " + " + l + " = " + v) + " m.",
      { ctx: "erreur", guide: [GS("Le tour du rectangle : " + M(L + " + " + l + " + " + L + " + " + l) + " = ?", v, M(v) + " m.")],
        traps: [TRAP(L * l, "C'est le calcul de " + w + " : c'est l'aire (m²), pas la longueur du tour."), TRAP(L + l, "Ça, c'est un demi-tour : il y a deux longueurs et deux largeurs.")] }); }));
  // pct : retrouver le tout à partir d'une partie (on prend le pourcentage de la partie).
  VA("pct", 2, () => { const t = R.pick([5, 10, 15, 20, 25, 40]), X = 20 * R.int(3, 30), N = (X * t) / 100, f = r6((N * t) / 100), w = who(), c = R.pick([["Un acompte de " + N + " CHF représente " + t + " % du prix d'un voyage.", "le prix du voyage (en CHF)"], ["Une remise de " + N + " CHF correspond à " + t + " % du prix d'un vélo.", "le prix du vélo avant la remise (en CHF)"]]);
    return QV(c[0] + " " + w + " calcule : « " + M(t + "\\,\\%") + " de " + M(N) + ", c'est " + M(nT(f)) + " CHF ». Trouve l'erreur, puis donne " + c[1] + ".", X,
      "Erreur : " + M(N) + " CHF est déjà la partie ; on cherche le tout (100 %). " + M("1\\,\\%") + " vaut " + M(N + " : " + t + " = " + nT(N / t)) + " CHF, donc 100 % valent " + M(nT(N / t) + " \\cdot 100 = " + nT(X)) + " CHF.",
      { ctx: "erreur", guide: [GS("Combien vaut 1 % du prix ? (" + M(N + " : " + t) + ")", N / t, M(nT(N / t)) + " CHF."), GS("Le prix entier (100 %) ?", X, M(nT(N / t) + " \\cdot 100 = " + nT(X)) + " CHF.")],
        traps: [TRAP(f, "C'est le calcul de " + w + " : " + N + " CHF est la partie, pas le tout."), TRAP(N + t, "On ne mélange pas des CHF et des pourcents.")] }); });
  // disque : aire calculée avec le diamètre.
  VA("disque", 2, () => { const d = R.int(4, 16), r = d / 2, v = Math.PI * r * r, f = Math.PI * d * d, w = who(), c = R.pick(["d'un disque", "d'une pizza", "d'un tapis rond", "d'une table ronde"]);
    return QV("Le diamètre " + c + " mesure " + M(d) + " cm. " + w + " calcule son aire : « " + M("\\pi \\cdot " + d + "^2 \\approx " + dec(Math.round(f * 10) / 10)) + " cm² ». Trouve l'erreur, puis donne l'aire (au dixième, en cm²).", v,
      "Erreur : la formule " + M("A = \\pi r^2") + " utilise le <b>rayon</b>, la moitié du diamètre : " + M("r = " + dec(r)) + " cm. " + M("A = \\pi \\cdot " + dec(r) + "^2 \\approx " + dec(Math.round(v * 10) / 10)) + " cm² (4 fois moins que le calcul de " + w + ").",
      { round: 0.1, ctx: "erreur", guide: [GS("Rayon (en cm) ?", r, M(dec(r)) + " cm."), GS("Aire " + M("\\pi r^2") + " ≈ ? (au dixième)", v, M("\\approx " + dec(Math.round(v * 10) / 10)) + " cm².", 0.1)],
        traps: [TRAP(f, "C'est le résultat de " + w + " : il faut le rayon, pas le diamètre."), TRAP(Math.PI * d, "Ça, c'est le périmètre du cercle.")] }); });
  // echelle : conversion cm → km avec 1 km = 1000 cm.
  VA("echelle", 2, () => clean(() => { const E = R.pick([10000, 20000, 25000, 50000]), c = R.int(5, 24) / 2, cm = r6(c * E), v = r6(cm / 100000), f = r6(cm / 1000), w = who();
    return QV("Sur une carte à l'échelle " + M("1\\,:\\," + nT(E)) + ", deux villages sont à " + M(dec(c)) + " cm l'un de l'autre. " + w + " écrit : « " + M(dec(c) + " \\cdot " + nT(E) + " = " + nT(cm)) + " cm, donc " + M(nT(f)) + " km ». Trouve l'erreur, puis donne la vraie distance en km.", v,
      "Erreur : " + M("1" + tu("km") + " = 1000" + tu("m") + " = 100\\text{'}000" + tu("cm")) + ", pas 1000 cm. " + M(nT(cm) + " : 100\\text{'}000 = " + nT(v)) + " km.",
      { ctx: "erreur", guide: [GS("Distance réelle en cm ?", cm, M(dec(c) + " \\cdot " + nT(E) + " = " + nT(cm)) + " cm."), GS("1 km = combien de cm ?", 100000, M("1000 \\cdot 100 = 100\\text{'}000") + " cm."), GS("Distance en km ?", v, M(nT(v)) + " km.")],
        traps: [TRAP(f, "C'est le résultat de " + w + " : 1 km = 100'000 cm."), TRAP(r6(cm / 100), "Ça, ce sont des mètres.")] }); }));
  // expo : a · b^x écrit (ab)^x.
  VA("expo", 2, () => { let a, b, n; do { a = R.pick([2, 3, 5]); b = R.pick([2, 3, 4, 5]); n = R.int(2, 4); } while (a === b || a * b ** n > 2000 || [a, b, a * b].includes(n)); const K = a * b ** n, f = Math.log(K) / Math.log(a * b), w = who();
    return QV(w + " résout " + M(a + " \\cdot " + b + "^x = " + nT(K)) + " : « " + M(a + " \\cdot " + b + "^x = " + a * b + "^x") + ", donc " + M("x = \\frac{\\log " + nT(K) + "}{\\log " + a * b + "} \\approx " + dec(r2(f))) + " ». Trouve l'erreur, puis résous correctement.", n,
      "Erreur : la puissance passe avant la multiplication, l'exposant " + M("x") + " ne porte que sur " + M(b) + " : " + M(a + " \\cdot " + b + "^x \\neq " + a * b + "^x") + ". On divise d'abord par " + M(a) + " : " + M(b + "^x = " + b ** n + " = " + b + "^{" + n + "}") + ", donc " + M("x = " + n) + ".",
      { ctx: "erreur", guide: [GS("Divise par " + M(a) + " : " + M(b + "^x") + " = ?", b ** n, M(nT(K) + " : " + a + " = " + b ** n) + "."), GS(M(b ** n) + " est quelle puissance de " + M(b) + " ? x = ?", n, M(b ** n + " = " + b + "^{" + n + "}") + ", donc " + M("x = " + n) + ".")],
        traps: [TRAP(r2(f), "C'est le résultat de " + w + " : " + M(a + " \\cdot " + b + "^x") + " n'est pas " + M(a * b + "^x") + ".")] }); });
  // log : log d'un produit pris comme produit des log.
  VA("log", 2, () => { const L = { 2: 0.301, 3: 0.477, 5: 0.699, 7: 0.845 }, [p, q] = R.pick([[2, 3], [2, 7], [3, 5], [3, 7], [5, 7], [2, 2], [3, 3]]), n = p * q, v = Math.log10(n), f = Math.round(L[p] * L[q] * 1000) / 1000, w = who();
    return QV("On donne " + M("\\log " + p + " \\approx " + dec(L[p])) + (p === q ? "" : " et " + M("\\log " + q + " \\approx " + dec(L[q]))) + ". " + w + " calcule : « " + M("\\log " + n + " = \\log " + p + " \\cdot \\log " + q + " \\approx " + dec(f)) + " ». Trouve l'erreur, puis donne " + M("\\log " + n) + " (au millième).", v,
      "Erreur : le logarithme d'un produit est la <b>somme</b> des logarithmes : " + M("\\log(" + p + " \\cdot " + q + ") = \\log " + p + " + \\log " + q + " \\approx " + dec(L[p]) + " + " + dec(L[q]) + " = " + dec(r6(L[p] + L[q]))) + ". Contrôle : " + M("10^{" + dec(r6(L[p] + L[q])) + "} \\approx " + n) + ".",
      { round: 0.001, ctx: "erreur", guide: [GS(M("\\log(" + p + " \\cdot " + q + ") = \\log " + p + " + \\log " + q) + " ≈ ? (au millième)", v, M("\\approx " + dec(r6(L[p] + L[q]))) + ".", 0.001)],
        traps: [TRAP(f, "C'est le résultat de " + w + " : " + M("\\log(ab) = \\log a + \\log b") + ", pas " + M("\\log a \\cdot \\log b") + ".")] }); });
  // modexp : pourcentages successifs additionnés (intérêts simples au lieu de composés).
  VA("modexp", 2, () => { const C = R.pick([800, 1000, 2000, 5000]), t = R.pick([2, 3, 4, 5]), n = R.int(5, 12), v = C * (1 + t / 100) ** n, f = r6(C * (1 + (n * t) / 100)), w = who(),
      c = R.pick([["Un capital de " + nT(C) + " CHF est placé à " + t + " % d'intérêts par an ; les intérêts s'ajoutent au capital chaque année.", "le capital"], ["Le loyer d'un local, " + nT(C) + " CHF par mois, augmente de " + t + " % chaque année.", "le loyer"]]);
    return QV(c[0] + " " + w + " calcule " + c[1] + " après " + n + " ans : « " + M(n + " \\cdot " + t + "\\,\\% = " + n * t + "\\,\\%") + ", donc " + M(nT(C) + " \\cdot " + dec(r6(1 + (n * t) / 100)) + " = " + nT(f)) + " CHF ». Trouve l'erreur, puis donne la bonne valeur (au centime).", v,
      "Erreur : chaque hausse de " + t + " % porte sur la valeur de l'année précédente, déjà augmentée : on multiplie " + n + " fois par " + M(dec(1 + t / 100)) + ". " + M(nT(C) + " \\cdot " + dec(1 + t / 100) + "^{" + n + "} \\approx " + nT(r2(v))) + " CHF.",
      { round: 0.01, ctx: "erreur", guide: [GS("Coefficient multiplicateur pour une année ?", 1 + t / 100, M("1 + " + dec(t / 100) + " = " + dec(1 + t / 100)) + "."), GS("Valeur après " + n + " ans : " + M(nT(C) + " \\cdot " + dec(1 + t / 100) + "^{" + n + "}") + " ≈ ? (au centime)", v, M("\\approx " + nT(r2(v))) + " CHF.", 0.01)],
        traps: [TRAP(f, "C'est le résultat de " + w + " : les pourcentages successifs ne s'additionnent pas, ils se multiplient.")] }); });
})();

// ======================= 25.11 : audit de niveau 9e–10e (tools/niveau_910.md) =======================
// Formes au programme de la classe, ajoutées là où l'audit a écarté des formes d'une année supérieure (HORS_CO, engine.js) :
// 9e : substitution avec des décimaux positifs (pas de produit de relatifs), volume d'un pavé ; 10e : simple distributivité,
// équations à parenthèses, échelles (longueurs seulement : aires × k² et volumes × k³ en 11e).
/* VARX : comme VAR, mais lu en plus de VAR par Engine.build ; les modules de chapitre (ch11_litt.js, ch11_no.js…) vident
   VAR[id] pour leurs notions, pas VARX. */
const VARX = {};
const PROBX = {}; /* défis (niveau 4) ajoutés, lus en plus de PROB et PROB_EXTRA par Engine.build */
(() => {
  /* g = classes du CO (grades) où la forme est proposée : ailleurs elle est écartée au tirage (q.co, horsCO dans engine.js),
     pour ne pas abaisser le niveau des autres classes (11e, Collège, MP). */
  const VA = (id, lv, g, ...fns) => { const w = fns.map((f) => () => { const q = f(); if (q) q.co = g; return q; }); for (const l of lv === 3 ? [3, 4] : [lv]) { VARX[id] = VARX[id] || {}; VARX[id][l] = (VARX[id][l] || []).concat(w); } };
  const who = () => R.pick(["Lina", "Noé", "Inès", "Yanis", "Mia", "Sam", "Léa", "Tom"]);
  const cx = (c, v) => (c === 1 ? v : c === -1 ? "-" + v : c + v); /* coefficient devant une lettre, en TeX */
  const sg = (c, v) => (c < 0 ? " - " + cx(-c, v) : " + " + cx(c, v)); /* terme suivant, avec son signe */
  const ex = (A, B) => A + "*x^2" + (B < 0 ? "-" + -B : "+" + B) + "*x"; /* Ax² + Bx pour le correcteur */
  const ex1 = (A, B) => A + "*x" + (B < 0 ? "-" + -B : "+" + B);
  const QXt = (q, e, sol, o) => Object.assign(QX(q, e, sol, o), o.traps ? { traps: o.traps } : {}); /* QX ne transmet pas les pièges */
  const GE = (ask, e, sol) => ({ ask, spec: { kind: "expr", expr: e, form: "reduced" }, sol });

  // --- 9e : valnum, niveau 3 (décimaux positifs) ---
  VA("valnum", 3, [9, 10],
    () => clean(() => { const a = R.pick([0.5, 1.5, 2.5, 1.2]), b = R.int(2, 9), c1 = R.int(2, 4), c2 = R.int(2, 5), a2 = r6(a * a), v = r6(c1 * a2 + c2 * a * b);
      return QV("Calcule " + M(c1 + "a^2 + " + c2 + "ab") + " pour " + M("a = " + dec(a)) + " et " + M("b = " + b) + ".", v,
        M(c1 + " \\cdot " + dec(a) + "^2 + " + c2 + " \\cdot " + dec(a) + " \\cdot " + b + " = " + c1 + " \\cdot " + dec(a2) + " + " + dec(r6(c2 * a * b)) + " = " + dec(v)) + ".",
        { ctx: "dec2", guide: [GS(M(dec(a) + "^2") + " = ?", a2, M(dec(a) + " \\cdot " + dec(a) + " = " + dec(a2)) + "."), GS(M(c1 + " \\cdot " + dec(a2)) + " = ?", r6(c1 * a2), M(dec(r6(c1 * a2))) + "."), GS(M(c2 + " \\cdot " + dec(a) + " \\cdot " + b) + " = ?", r6(c2 * a * b), M(dec(r6(c2 * a * b))) + "."), GS("Total ?", v, M(dec(v)) + ".")],
          traps: [TRAP(r6(c1 * 2 * a + c2 * a * b), M("a^2 = a \\cdot a") + ", pas " + M("2 \\cdot a") + "."), TRAP(r6((c1 * a) ** 2 + c2 * a * b), "Le carré ne porte que sur " + M("a") + " : calcule " + M("a^2") + ", puis multiplie par " + c1 + ".")] }); }),
    () => clean(() => { const a = R.pick([2.5, 1.5, 3.5, 4.5]), b = R.int(3, 8), c = R.pick([1.2, 0.8, 2, 0.5]), ab = r6(a * b), bc = r6(b * c), ac = r6(a * c), v = r6(2 * (ab + bc + ac));
      return QV("L'aire totale d'un pavé droit de dimensions " + M("a") + ", " + M("b") + " et " + M("c") + " vaut " + M("A = 2(ab + bc + ac)") + ". Calcule " + M("A") + " pour " + M("a = " + dec(a)) + " cm, " + M("b = " + b) + " cm et " + M("c = " + dec(c)) + " cm (en cm²).", v,
        M("A = 2(" + dec(ab) + " + " + dec(bc) + " + " + dec(ac) + ") = 2 \\cdot " + dec(r6(ab + bc + ac)) + " = " + dec(v)) + " cm².",
        { ctx: "formule-pave", guide: [GS(M("ab") + " = ?", ab, M(dec(ab)) + "."), GS(M("bc") + " = ?", bc, M(dec(bc)) + "."), GS(M("ac") + " = ?", ac, M(dec(ac)) + "."), GS(M("A = 2(ab + bc + ac)") + " = ?", v, M(dec(v)) + " cm².")],
          traps: [TRAP(r6(ab + bc + ac), "N'oublie pas le facteur 2 : chaque face a sa face opposée."), TRAP(r6(a * b * c), "Ça, c'est le volume.")] }); }),
    () => clean(() => { const x = R.pick([0.5, 1.5, 2.5]), k = R.pick([2, 4]), m = R.int(1, 5), n = R.int(2, 6), in1 = r6(k * x + m), v = r6(in1 * in1 - n * x);
      return QV("Calcule " + M("(" + k + "x + " + m + ")^2 - " + n + "x") + " pour " + M("x = " + dec(x)) + ".", v,
        M("(" + k + " \\cdot " + dec(x) + " + " + m + ")^2 - " + n + " \\cdot " + dec(x) + " = " + dec(in1) + "^2 - " + dec(r6(n * x)) + " = " + dec(r6(in1 * in1)) + " - " + dec(r6(n * x)) + " = " + dec(v)) + ".",
        { ctx: "carre-dec", guide: [GS("La parenthèse d'abord : " + M(k + " \\cdot " + dec(x) + " + " + m) + " = ?", in1, M(dec(in1)) + "."), GS("Son carré ?", r6(in1 * in1), M(dec(in1) + "^2 = " + dec(r6(in1 * in1))) + "."), GS("Résultat ?", v, M(dec(v)) + ".")],
          traps: [TRAP(r6((k * x) ** 2 + m * m - n * x), "Le carré d'une somme n'est pas la somme des carrés : calcule d'abord la parenthèse."), TRAP(r6(2 * in1 - n * x), "Le carré : la parenthèse multipliée par elle-même, pas par 2.")] }); }),
  );
  // --- 9e : prio, niveau 3 (sans produit de relatifs ; puissances de décimaux positifs) ---
  VA("prio", 3, [9, 10],
    () => clean(() => { let a, b, c; do { a = R.int(30, 90); b = R.int(5, 9); c = R.int(2, 4); } while (a <= (b - c) ** 2); const v = a - (b - c) ** 2;
      return QV("Calcule : " + M(a + " - (" + b + " - " + c + ")^2"), v, M(a + " - " + (b - c) + "^2 = " + a + " - " + (b - c) ** 2 + " = " + v) + ".",
        { ctx: "carre-pos", guide: [GS("La parenthèse : " + M(b + " - " + c) + " = ?", b - c, M(b - c) + "."), GS("Son carré ?", (b - c) ** 2, M((b - c) + "^2 = " + (b - c) ** 2) + "."), GS("Résultat ?", v, M(v) + ".")],
          traps: [TRAP(a - b * b + c * c, "On calcule d'abord la parenthèse, puis son carré."), TRAP((a - b + c) ** 2, "La puissance passe avant la soustraction.")] }); }),
    () => { let a, b, s, j, k; do { a = R.int(1, 4); b = R.int(1, 4); s = (a + b) ** 2; j = R.int(3, 9); k = R.int(1, j - 2); } while (a === b || [a, b, k].includes(j - k)); const m = j * s;
      return QV("Calcule : " + M(m + " : (" + a + " + " + b + ")^2 - " + k), j - k, M(m + " : " + (a + b) + "^2 - " + k + " = " + m + " : " + s + " - " + k + " = " + j + " - " + k + " = " + (j - k)) + ".",
        { ctx: "quotient-carre", guide: [GS(M("(" + a + " + " + b + ")^2") + " = ?", s, M((a + b) + "^2 = " + s) + "."), GS(M(m + " : " + s) + " = ?", j, M(j) + "."), GS("Résultat ?", j - k, M(j - k) + ".")],
          traps: [TRAP(m / (a * a + b * b) - k, M("(a + b)^2") + " n'est pas " + M("a^2 + b^2") + " : calcule d'abord la parenthèse.")].filter((t) => Number.isInteger(t.v)) }); },
    () => clean(() => { const x = R.pick([1.5, 2.5, 0.5, 1.2]), c = R.int(2, 4), d = R.int(2, 5), y = R.pick([0.4, 0.6, 0.8, 1.5]), e = R.int(4, 9), x2 = r6(x * x), v = r6(c * x2 + d * (e - y));
      return QV("Calcule : " + M(c + " \\cdot " + dec(x) + "^2 + " + d + " \\cdot (" + e + " - " + dec(y) + ")"), v, M(c + " \\cdot " + dec(x2) + " + " + d + " \\cdot " + dec(r6(e - y)) + " = " + dec(r6(c * x2)) + " + " + dec(r6(d * (e - y))) + " = " + dec(v)) + ".",
        { ctx: "puiss-dec", guide: [GS(M(dec(x) + "^2") + " = ?", x2, M(dec(x2)) + "."), GS("La parenthèse : " + M(e + " - " + dec(y)) + " = ?", r6(e - y), M(dec(r6(e - y))) + "."), GS("Résultat ?", v, M(dec(v)) + ".")],
          traps: [TRAP(r6((c * x) ** 2 + d * (e - y)), "La puissance ne porte que sur " + M(dec(x)) + " : calcule " + M(dec(x) + "^2") + " puis multiplie par " + c + "."), TRAP(r6(c * 2 * x + d * (e - y)), M(dec(x) + "^2 = " + dec(x) + " \\cdot " + dec(x)) + ", pas " + M("2 \\cdot " + dec(x)) + ".")] }); }),
  );
  // --- 9e : angtri, niveau 3 (triangles et quadrilatères ; polygones réguliers en 10e) ---
  VA("angtri", 3, [9],
    () => { let a; do a = R.int(55, 125); while (a === 90); return QV("Un trapèze rectangle a deux angles droits. Un autre de ses angles mesure " + a + "°. Combien mesure le quatrième (en degrés) ?", 180 - a, M("360° - 90° - 90° - " + a + "° = " + (180 - a) + "°") + ".",
      { ctx: "trapeze", guide: [GS("Somme des angles d'un quadrilatère (en degrés) ?", 360, "360°."), GS("Quatrième angle ?", 180 - a, M("360° - 180° - " + a + "° = " + (180 - a) + "°") + ".")], traps: [TRAP(360 - a, "Il y a aussi les deux angles droits à retirer."), TRAP(90 - a > 0 ? 90 - a : 270 - a, "Somme des angles d'un quadrilatère : 360°.")] }); },
    () => { let a; do a = R.int(72, 98); while (a === 90); return QV("Un quadrilatère a trois angles égaux de " + a + "° chacun. Combien mesure le quatrième (en degrés) ?", 360 - 3 * a, M("360° - 3 \\cdot " + a + "° = " + (360 - 3 * a) + "°") + ".",
      { ctx: "trois-egaux", guide: [GS("Somme des trois angles égaux ?", 3 * a, M("3 \\cdot " + a + "° = " + 3 * a + "°") + "."), GS("Quatrième angle ?", 360 - 3 * a, M("360° - " + 3 * a + "° = " + (360 - 3 * a) + "°") + ".")], traps: [TRAP(180 - 3 * a > 0 ? 180 - 3 * a : 360 - a, "Quadrilatère : la somme des angles vaut 360°."), TRAP(360 - a, "Il y a trois angles de " + a + "° à retirer.")] }); },
    () => { let x, d, e; do { x = R.int(30, 50); d = R.int(5, 25); e = 180 - 3 * x - d; } while (e < 5 || e > 40 || e === d);
      return QV("Dans un triangle, un angle mesure " + d + "° de plus que le plus petit, et le troisième " + e + "° de plus que le plus petit. Combien mesure le plus petit angle (en degrés) ?", x, M("x + (x + " + d + ") + (x + " + e + ") = 180") + ", " + M("3x = " + (180 - d - e)) + ", " + M("x = " + x) + "°.",
        { ctx: "ecarts", guide: [GS("Retire les écarts à 180° : " + M("180 - " + d + " - " + e) + " = ?", 180 - d - e, M(180 - d - e) + "°."), GS("Partage en trois angles égaux : le plus petit ?", x, M((180 - d - e) + " : 3 = " + x) + "°.")], traps: [TRAP(60, "Les trois angles ne sont pas égaux : retire d'abord les écarts."), TRAP(x + e, "C'est le plus grand angle.")] }); },
  );
  // --- 9e : fracadd, niveau 3 (dans Q+) ---
  VA("fracadd", 3, [9, 10],
    () => clean(() => { let b, d, f, a, c, g, n, D; do { [b, d, f] = R.pick([[6, 4, 3], [4, 6, 12], [3, 4, 6], [5, 10, 4], [8, 6, 3], [9, 6, 4]]); a = R.int(1, b - 1); c = R.int(1, d - 1); g = R.int(1, f - 1); D = b * d * f / gcd(b * d * f, 1); n = a / b - c / d + g / f; } while (n <= 0 || gcd(a, b) !== 1 || gcd(c, d) !== 1 || gcd(g, f) !== 1);
      const L = [b, d, f].reduce((p, q) => (p * q) / gcd(p, q)), N = Math.round(n * L), G = gcd(N, L);
      return QV("Calcule et donne le résultat sous forme de fraction irréductible : " + M("\\frac{" + a + "}{" + b + "} - \\frac{" + c + "}{" + d + "} + \\frac{" + g + "}{" + f + "}"), n,
        "Dénominateur commun " + L + " : " + M("\\frac{" + (a * L) / b + "}{" + L + "} - \\frac{" + (c * L) / d + "}{" + L + "} + \\frac{" + (g * L) / f + "}{" + L + "} = \\frac{" + N + "}{" + L + "}" + (G > 1 ? " = \\frac{" + N / G + "}{" + L / G + "}" : "")) + ".",
        { ctx: "trois-pos", guide: [GS("Plus petit dénominateur commun ?", L, M(L) + "."), GS("Numérateur sur " + L + " ?", N, M((a * L) / b + " - " + (c * L) / d + " + " + (g * L) / f + " = " + N) + "."), GS("Résultat (fraction irréductible) ?", n, M((G > 1 ? "\\frac{" + N / G + "}{" + L / G + "}" : "\\frac{" + N + "}{" + L + "}")) + ".")],
          traps: [TRAP((a - c + g) / (b + d + f), "On n'additionne pas les dénominateurs : on met au même dénominateur."), TRAP(a / b + c / d + g / f, "Attention au signe − devant " + M("\\frac{" + c + "}{" + d + "}") + ".")] }); }),
    () => clean(() => { const e = R.int(2, 4), [b, d] = R.pick([[4, 6], [3, 4], [6, 8], [4, 10], [3, 5]]), a = R.int(1, b - 1), c = R.int(1, d - 1), v = e - a / b - c / d, L = (b * d) / gcd(b, d), N = Math.round(v * L), G = gcd(N, L);
      return QV("Calcule et donne le résultat sous forme de fraction irréductible : " + M(e + " - \\frac{" + a + "}{" + b + "} - \\frac{" + c + "}{" + d + "}"), v,
        M(e + " = \\frac{" + e * L + "}{" + L + "}") + " ; " + M("\\frac{" + e * L + " - " + (a * L) / b + " - " + (c * L) / d + "}{" + L + "} = \\frac{" + N + "}{" + L + "}" + (G > 1 ? " = \\frac{" + N / G + "}{" + L / G + "}" : "")) + ".",
        { ctx: "entier-moins", guide: [GS("Dénominateur commun ?", L, M(L) + "."), GS(M(e) + " écrit sur " + L + " : numérateur ?", e * L, M(e * L) + "."), GS("Résultat (fraction irréductible) ?", v, M(G > 1 ? "\\frac{" + N / G + "}{" + L / G + "}" : "\\frac{" + N + "}{" + L + "}") + ".")],
          traps: [TRAP((e - a - c) / L, "L'entier " + e + " s'écrit aussi sur " + L + " : " + M("\\frac{" + e * L + "}{" + L + "}") + "."), TRAP(e - a / b + c / d, "Les deux fractions sont retirées.")] }); }),
  );
  // --- 9e : quadri, niveau 3 (propriétés des diagonales et somme des angles ; « axes de symétrie d'un carré » = primaire) ---
  VA("quadri", 3, [9],
    () => { const x = 2 * R.int(19, 41), v = (180 - x) / 2;
      return QV("Dans un rectangle " + M("ABCD") + ", les diagonales se coupent en " + M("O") + " et l'angle " + M("\\widehat{AOB}") + " mesure " + x + "°. Combien mesure l'angle " + M("\\widehat{OAB}") + " (en degrés) ?", v,
        "Les diagonales d'un rectangle ont la même longueur et se coupent en leur milieu : " + M("OA = OB") + ", le triangle " + M("AOB") + " est isocèle. " + M("\\widehat{OAB} = (180° - " + x + "°) : 2 = " + v + "°") + ".",
        { ctx: "rect-diag", guide: [GS("Le triangle AOB est isocèle en O. Somme de ses deux angles à la base (en degrés) ?", 180 - x, M("180° - " + x + "° = " + (180 - x) + "°") + "."), GS(M("\\widehat{OAB}") + " = ?", v, M((180 - x) + "° : 2 = " + v + "°") + ".")],
          traps: [TRAP(180 - x, "Les deux angles à la base se partagent ce reste : divise par 2."), TRAP(90 - x / 2 === v ? x / 2 : 90 - x / 2, "Utilise le triangle isocèle AOB.")] }); },
    () => { const a = 2 * R.int(28, 62), v = (180 - a) / 2;
      return QV("Dans un losange " + M("ABCD") + ", l'angle " + M("\\widehat{ABC}") + " mesure " + a + "°. Combien mesure l'angle " + M("\\widehat{BAC}") + " entre le côté " + M("[AB]") + " et la diagonale " + M("[AC]") + " (en degrés) ?", v,
        "Les côtés d'un losange sont égaux : " + M("BA = BC") + ", le triangle " + M("ABC") + " est isocèle en " + M("B") + ". " + M("\\widehat{BAC} = (180° - " + a + "°) : 2 = " + v + "°") + ".",
        { ctx: "losange-diag", guide: [GS("Le triangle ABC est isocèle en B. Que mesurent ensemble ses deux autres angles (en degrés) ?", 180 - a, M("180° - " + a + "° = " + (180 - a) + "°") + "."), GS(M("\\widehat{BAC}") + " = ?", v, M((180 - a) + "° : 2 = " + v + "°") + ".")],
          traps: [TRAP(a / 2, "C'est la moitié de l'angle en B ; l'angle cherché est en A, dans le triangle isocèle ABC."), TRAP(180 - a, "Les deux angles à la base se partagent ce reste : divise par 2.")] }); },
  );
  // --- 9e : litelab, niveau 3 (écrire sans réduire) ---
  VA("litelab", 3, [9, 10],
    () => { const k = R.int(2, 7), m = R.int(3, 9), e = m + "*x*(x+" + k + ")";
      return QXt("Un pavé droit a pour dimensions " + M("x") + ", " + M("x + " + k) + " et " + M(m) + " (en cm). Écris son volume.", e, M("V = " + m + "x(x + " + k + ")") + " cm³ (ou, développé, " + M(m + "x^2 + " + m * k + "x") + ").",
        { ctx: "pave", guide: [{ ask: "Volume = produit des trois dimensions. Écris-le (avec des parenthèses autour de " + M("x + " + k) + ").", spec: { kind: "expr", expr: e }, sol: M(m + "x(x + " + k + ")") + "." }], traps: [{ e: "x+x+" + k + "+" + m, m: "Le volume est un produit, pas une somme." }, { e: m + "*x*x+" + k, m: "Il faut des parenthèses : c'est toute la longueur " + M("x + " + k) + " qui est multipliée." }] }); },
  );

  // --- Défis (niveau 4) de la classe : remplacent ceux d'une année supérieure écartés en 9e (polygones réguliers) et en 10e
  // (double distributivité, aires et volumes agrandis) ---
  const PX = (id, g, f) => { (PROBX[id] = PROBX[id] || []).push(() => Object.assign(f(), { co: g })); };
  const PB = (q, parts, hints, sol) => ({ q, parts: parts.map(([label, value]) => ({ label, spec: { kind: "value", value } })), hints, sol });
  PX("angtri", [9], () => { const a = R.pick([20, 28, 36, 44, 52, 68, 76, 84, 92, 100]), b = (180 - a) / 2, h = b / 2, d = 180 - a - h;
    return PB("Le triangle " + M("ABC") + " est isocèle en " + M("A") + " et l'angle au sommet " + M("\\widehat{BAC}") + " mesure " + a + "°. La bissectrice de l'angle " + M("\\widehat{ABC}") + " coupe le côté " + M("[AC]") + " en " + M("D") + ".",
      [["a) Angle " + M("\\widehat{ABC}") + " (en degrés)", b], ["b) Angle " + M("\\widehat{ABD}") + " (en degrés)", h], ["c) Angle " + M("\\widehat{ADB}") + " (en degrés)", d]],
      ["Isocèle en A : les angles en B et en C sont égaux ; ensemble, ils font 180° − " + a + "°.", "La bissectrice partage l'angle en B en deux angles égaux ; puis somme des angles du triangle ABD."],
      "a) " + M("(180° - " + a + "°) : 2 = " + b + "°") + ". b) " + M(b + "° : 2 = " + h + "°") + ". c) Dans le triangle " + M("ABD") + " : " + M("180° - " + a + "° - " + h + "° = " + d + "°") + "."); });
  PX("distrib", [10], () => { const a = R.int(2, 7), b = R.int(3, 6), c = R.int(2, 5), n = R.int(3, 8), A1 = b * (n + a), T = n * n + (b + c) * n + a * b;
    return PB("Une figure est formée de deux rectangles accolés : le premier mesure " + M("x + " + a) + " sur " + M(b) + ", le second " + M("x") + " sur " + M("x + " + c) + " (en m).",
      [["a) Aire du premier rectangle pour " + M("x = " + n) + " (m²)", A1], ["b) L'aire totale, développée et réduite, s'écrit " + M("x^2 + \\ldots x + \\ldots") + " : coefficient de " + M("x"), b + c], ["c) Terme constant de cette aire totale", a * b], ["d) Aire totale pour " + M("x = " + n) + " (m²)", T]],
      ["Premier rectangle : " + b + "(x + " + a + ") ; second : x(x + " + c + "). Développe chacun (simple distributivité).", "Additionne et regroupe les termes semblables, puis remplace x par " + n + "."],
      M(b + "(x + " + a + ") + x(x + " + c + ") = " + b + "x + " + a * b + " + x^2 + " + c + "x = x^2 + " + (b + c) + "x + " + a * b) + ". a) " + M(b + " \\cdot " + (n + a) + " = " + A1) + " m². d) " + M(n * n + " + " + (b + c) * n + " + " + a * b + " = " + T) + " m²."); });
  PX("echelle", [10], () => { const E = R.pick([25000, 50000, 20000]), t = [R.int(21, 69) / 10, R.int(21, 69) / 10, R.int(11, 49) / 10], L = r6(t[0] + t[1] + t[2]), km = r6((L * E) / 100000), E2 = E === 50000 ? 25000 : 50000, L2 = r6((L * E) / E2);
    return PB("Sur une carte au " + M("1\\,:\\," + mille(E)) + ", un itinéraire de randonnée compte trois tronçons de " + M(dec(t[0])) + " cm, " + M(dec(t[1])) + " cm et " + M(dec(t[2])) + " cm.",
      [["a) Longueur de l'itinéraire sur la carte (cm)", L], ["b) Longueur réelle (km)", km], ["c) Longueur de cet itinéraire sur une carte au " + M("1\\,:\\," + mille(E2)) + " (cm)", L2]],
      ["Longueur réelle en cm = longueur sur la carte · " + mille(E) + ", puis 1 km = 100'000 cm.", "Sur l'autre carte : longueur réelle en cm divisée par " + mille(E2) + "."],
      "a) " + M(dec(L)) + " cm. b) " + M(dec(L) + " \\cdot " + mille(E) + " = " + mille(r6(L * E))) + " cm = " + M(dec(km)) + " km. c) " + M(mille(r6(L * E)) + " \\div " + mille(E2) + " = " + dec(L2)) + " cm."); });
  // --- 10e : distrib (simple distributivité seulement) ---
  VA("distrib", 2, [10],
    () => { let a, b, c, d, e, f; do { a = R.int(2, 6); b = R.int(2, 5); c = R.int(1, 9); d = R.int(2, 6); e = R.int(1, 5); f = R.int(1, 9); } while (a * b === d * e || d * f === a * c);
      const A = a * b - d * e, B = d * f - a * c;
      return QXt("Développe et réduis : " + M(a + "(" + b + "x - " + c + ") - " + d + "(" + cx(e, "x") + " - " + f + ")") + ".", ex1(A, B), M(cx(a * b, "x") + " - " + a * c + " - " + cx(d * e, "x") + " + " + d * f + " = " + cx(A, "x") + (B < 0 ? " - " + -B : " + " + B)) + ".",
        { form: "reduced", ctx: "deuxsimples", guide: [GE("Développe " + M(a + "(" + b + "x - " + c + ")") + " :", ex1(a * b, -a * c), M(cx(a * b, "x") + " - " + a * c) + "."), GE("Développe " + M("-" + d + "(" + cx(e, "x") + " - " + f + ")") + " (attention au signe −) :", ex1(-d * e, d * f), M(cx(-d * e, "x") + " + " + d * f) + "."), GE("Réduis le tout :", ex1(A, B), M(cx(A, "x") + (B < 0 ? " - " + -B : " + " + B)) + ".")],
          traps: [{ e: ex1(A, -a * c - d * f), m: "Le signe − devant " + M(d) + " porte sur tout le contenu de la parenthèse : " + M("-" + d + " \\cdot (-" + f + ") = +" + d * f) + "." }] }); },
  );
  VA("distrib", 3, [10],
    () => { let a, b, c, d, e, f, g, A, B; do { a = R.int(2, 4); b = R.int(2, 5); c = R.int(1, 6); d = R.int(1, 3); e = R.int(1, 4); f = R.int(1, 6); g = R.int(2, 9); A = a * b - d * e; B = -a * c - d * f + g; } while (A === 0 || B === 0);
      const t = cx(a, "x") + "(" + b + "x - " + c + ") - " + cx(d, "x") + "(" + cx(e, "x") + " + " + f + ") + " + g + "x";
      return QXt("Développe et réduis : " + M(t) + ".", ex(A, B), M(a * b + "x^2 - " + a * c + "x - " + cx(d * e, "x^2") + " - " + cx(d * f, "x") + " + " + g + "x = " + cx(A, "x^2") + sg(B, "x")) + ".",
        { form: "reduced", ctx: "troisdev", guide: [GE("Développe " + M(cx(a, "x") + "(" + b + "x - " + c + ")") + " :", ex(a * b, -a * c), M(a * b + "x^2 - " + a * c + "x") + "."), GE("Développe " + M("-" + cx(d, "x") + "(" + cx(e, "x") + " + " + f + ")") + " :", ex(-d * e, -d * f), M("-" + cx(d * e, "x^2") + " - " + cx(d * f, "x")) + "."), GE("Ajoute " + M(g + "x") + " et réduis :", ex(A, B), M(cx(A, "x^2") + sg(B, "x")) + ".")],
          traps: [{ e: ex(a * b + d * e, B), m: "Le signe − devant " + M(cx(d, "x")) + " change le signe de " + M(cx(d * e, "x^2")) + "." }, { e: ex(A, -a * c + d * f + g), m: M("-" + cx(d, "x") + " \\cdot " + f + " = -" + cx(d * f, "x")) + " : le signe − porte sur les deux termes." }] }); },
  );

  // --- 10e : eq1, niveau 3 (parenthèses des deux côtés, décimaux) ---
  VA("eq1", 3, [10],
    () => { let a, b, c, d, e, f, x0, g, k; do { a = R.int(3, 8); b = R.int(1, 6); c = R.int(2, 5); d = R.int(1, 6); e = R.int(2, 4); f = R.int(1, 6); x0 = R.pick([-7, -5, -4, -3, -2, 2, 3, 4, 5, 6, 8]); k = a - c - e; g = a * (x0 - b) - c * (x0 + d) - e * (x0 - f); } while (k === 0 || g === 0 || Math.abs(g) > 60 || a === c);
      const L0 = -a * b - c * d, R0 = -e * f + g, xw = (-e * f + g + a * b - c * d) / (a - c - e);
      return QV("Résous : " + M(a + "(x - " + b + ") - " + c + "(x + " + d + ") = " + e + "(x - " + f + ")" + (g < 0 ? " - " + -g : " + " + g)) + ".", x0,
        "Gauche : " + M(cx(a - c, "x") + (L0 < 0 ? " - " + -L0 : " + " + L0)) + " ; droite : " + M(cx(e, "x") + (R0 < 0 ? " - " + -R0 : " + " + R0)) + ". Donc " + M(cx(k, "x") + " = " + (R0 - L0)) + " et " + M("x = " + x0) + ".",
        { ctx: "paren3", guide: [GS("Développe et réduis le membre de gauche. Coefficient de " + M("x") + " ?", a - c, M(cx(a - c, "x")) + "."), GS("Et son nombre (terme constant) ?", L0, M(-a * b + " - " + c * d + " = " + L0) + "."), GS("Développe le membre de droite : terme constant ?", R0, M(-e * f + (g < 0 ? " - " + -g : " + " + g) + " = " + R0) + "."), GS("Solution " + M("x") + " ?", x0, M(cx(k, "x") + " = " + (R0 - L0)) + ", " + M("x = " + x0) + ".")],
          traps: Number.isFinite(xw) ? [TRAP(xw, "Le signe − devant " + M(c) + " porte sur les deux termes : " + M("-" + c + "(x + " + d + ") = -" + c + "x - " + c * d) + ".")] : [] }); },
    () => { let p, q, b, x0, r; do { p = R.pick([1.5, 2.5, 0.5, 1.2, 3.5]); q = R.pick([0.5, 0.3, 2, 0.8, 1.5]); b = R.int(2, 6); x0 = R.int(2, 14); r = r6(p * (x0 - b) - q * x0); } while (p === q || r === 0 || x0 === b || Math.abs(r * 100 - Math.round(r * 100)) > 1e-6);
      const xw = r6((r + b) / (p - q));
      return QV("Résous : " + M(dec(p) + "(x - " + b + ") = " + dec(q) + "x" + (r < 0 ? " - " + dec(-r) : " + " + dec(r))) + ".", x0,
        M(dec(p) + "x - " + dec(r6(p * b)) + " = " + dec(q) + "x" + (r < 0 ? " - " + dec(-r) : " + " + dec(r))) + ", donc " + M(dec(r6(p - q)) + "x = " + dec(r6(r + p * b))) + " et " + M("x = " + x0) + ".",
        { ctx: "decparen", guide: [GS("Développe : " + M(dec(p) + " \\cdot " + b) + " = ?", r6(p * b), M(dec(r6(p * b))) + "."), GS("Après avoir regroupé les " + M("x") + " à gauche : coefficient de " + M("x") + " ?", r6(p - q), M(dec(p) + " - " + dec(q) + " = " + dec(r6(p - q))) + "."), GS("Solution " + M("x") + " ?", x0, M("x = " + dec(r6(r + p * b)) + " \\div " + dec(r6(p - q)) + " = " + x0) + ".")],
          traps: xw !== x0 ? [TRAP(xw, "Développe toute la parenthèse : " + M(dec(p) + " \\cdot " + b) + " aussi.")] : [] }); },
  );

  // --- 10e : echelle (longueurs) ---
  VA("echelle", 2, [10],
    () => { const E = R.pick([25000, 50000, 20000, 100000]), c = R.pick([3.4, 4.6, 7.2, 5.8, 9.5, 12.4]), v = r6((c * E) / 100000);
      return QV("Sur une carte au " + M("1\\,:\\," + mille(E)) + ", un lac mesure " + M(dec(c)) + " cm de long. Quelle est sa longueur réelle, en km ?", v, M(dec(c) + " \\cdot " + mille(E) + " = " + mille(r6(c * E))) + " cm = " + M(dec(v)) + " km.",
        { ctx: "carte-reel", guide: [GS("Longueur réelle en cm ?", r6(c * E), M(mille(r6(c * E))) + " cm."), GS("En km (1 km = 100'000 cm) ?", v, M(dec(v)) + " km.")], traps: [TRAP(r6((c * E) / 1000), "1 km = 100'000 cm, pas 1'000 cm."), TRAP(r6((c * E) / 100), "Ça, ce sont des mètres.")] }); },
    () => { const E = R.pick([25000, 50000, 20000, 40000]), c = R.pick([4, 6, 8, 12, 14, 18]), km = r6((c * E) / 100000);
      return QV("Un sentier de " + M(dec(km)) + " km mesure " + M(c) + " cm sur une carte. L'échelle de la carte est " + M("1\\,:\\,n") + ". Que vaut " + M("n") + " ?", E, M(dec(km) + " \\text{ km} = " + mille(r6(km * 100000)) + "\\text{ cm}") + " ; " + M(mille(r6(km * 100000)) + " \\div " + c + " = " + mille(E)) + ".",
        { ctx: "trouver-n", guide: [GS("Longueur réelle en cm ?", r6(km * 100000), M(mille(r6(km * 100000))) + " cm."), GS(M("n") + " = ?", E, M(mille(r6(km * 100000)) + " \\div " + c + " = " + mille(E)) + ".")], traps: [TRAP(r6((km * 1000) / c), "Convertis d'abord les km en cm (même unité sur la carte et en réalité)."), TRAP(r6(E / 100), "1 km = 100'000 cm.")] }); },
  );
  VA("echelle", 3, [10],
    () => { let E1, E2, c, v; do { [E1, E2] = R.pick([[25000, 50000], [50000, 25000], [20000, 50000], [50000, 20000], [10000, 25000], [25000, 10000], [100000, 25000]]); c = R.pick([4, 6, 8, 10, 12, 14]); v = r6((c * E1) / E2); } while (Math.abs(v * 10 - Math.round(v * 10)) > 1e-9);
      return QV("Sur une carte au " + M("1\\,:\\," + mille(E1)) + ", deux refuges sont à " + M(c) + " cm l'un de l'autre. À quelle distance sont-ils sur une carte au " + M("1\\,:\\," + mille(E2)) + " (en cm) ?", v,
        "Distance réelle : " + M(c + " \\cdot " + mille(E1) + " = " + mille(c * E1)) + " cm ; sur l'autre carte : " + M(mille(c * E1) + " \\div " + mille(E2) + " = " + dec(v)) + " cm.",
        { ctx: "deux-cartes", guide: [GS("Distance réelle en cm ?", c * E1, M(mille(c * E1)) + " cm."), GS("Sur la carte au " + M("1\\,:\\," + mille(E2)) + " (en cm) ?", v, M(dec(v)) + " cm.")], traps: [TRAP(r6((c * E2) / E1), "Plus le nombre n de l'échelle est grand, plus la carte est réduite : la distance y est " + (E2 > E1 ? "plus petite" : "plus grande") + ".")] }); },
    () => { const E = R.pick([50, 100, 125]), [Lp, lp] = R.pick([[6.4, 4.5], [5.6, 3.2], [8, 4.4], [4.8, 3.6], [7.2, 5.4]]), Lr = r6((Lp * E) / 100), v = r6((lp * E) / 100);
      return QV("Sur le plan d'un appartement, le salon mesure " + M(dec(Lp)) + " cm sur " + M(dec(lp)) + " cm. En réalité, sa longueur est de " + M(dec(Lr)) + " m. Quelle est sa largeur réelle (en m) ?", v,
        "Échelle : " + M(dec(Lr) + " \\text{ m} = " + dec(r6(Lr * 100)) + "\\text{ cm}") + ", " + M(dec(r6(Lr * 100)) + " \\div " + dec(Lp) + " = " + E) + " : " + M("1\\,:\\," + E) + ". Largeur : " + M(dec(lp) + " \\cdot " + E + " = " + dec(r6(lp * E))) + " cm = " + M(dec(v)) + " m.",
        { ctx: "plan", guide: [GS("Échelle " + M("1\\,:\\,n") + " : que vaut " + M("n") + " ?", E, M(dec(r6(Lr * 100)) + " \\div " + dec(Lp) + " = " + E) + "."), GS("Largeur réelle en cm ?", r6(lp * E), M(dec(r6(lp * E))) + " cm."), GS("En m ?", v, M(dec(v)) + " m.")], traps: [TRAP(r6(lp * E), "Ça, ce sont des cm : divise par 100.")] }); },
    () => { const n = R.pick([87, 160, 45, 220, 32]), c = R.int(Math.ceil(1200 / n), Math.floor(2500 / n)), m = r6((c * n) / 100);
      return QV("Une locomotive réelle mesure " + M(dec(m)) + " m de long ; sa maquette mesure " + M(c) + " cm. L'échelle de la maquette est " + M("1\\,:\\,n") + ". Que vaut " + M("n") + " ?", n, M(dec(m) + " \\text{ m} = " + dec(r6(m * 100)) + "\\text{ cm}") + " ; " + M(dec(r6(m * 100)) + " \\div " + c + " = " + n) + ".",
        { ctx: "maquette-n", guide: [GS("Longueur réelle en cm ?", r6(m * 100), M(dec(r6(m * 100))) + " cm."), GS(M("n") + " = ?", n, M(dec(r6(m * 100)) + " \\div " + c + " = " + n) + ".")], traps: [TRAP(r6(m / c), "Mets les deux longueurs dans la même unité (cm) avant de diviser.")] }); },
  );
})();

// ===================== 25.11 : défis (niveau 4) du secondaire II encore manquants =====================
// Sonde de couverture du 25.11 : optim (1re Collège, MP 2e) n'avait aucun défi ; arith, fracper (1re Collège), arith,
// premiers, rac (MP 1re) n'avaient que les défis du Cycle, écartés au secondaire II. Classes : co (Collège, grade),
// mp (MP, grade), lus par horsCO (engine.js). Chargé après variantes.js (PROBX).
(() => {
  if (typeof PROBX === "undefined") return;
  const ri = R.int, pk = R.pick;
  const r6 = (v) => Math.round(v * 1e6) / 1e6;
  const N = (v) => { const s = String(r6(v)), neg = s[0] === "-", [i, f] = (neg ? s.slice(1) : s).split("."); return (neg ? "-" : "") + (+i >= 1000 ? i.replace(/\B(?=(\d{3})+(?!\d))/g, "\\text{'}") : i) + (f ? "{,}" + f : ""); };
  const X = (v) => M(N(v));
  const PX = (id, cl, f) => { (PROBX[id] = PROBX[id] || []).push(() => Object.assign(f(), cl)); };
  const PB = (q, parts, hints, sol) => ({ q, hints, sol, parts: parts.map(([label, v, rd]) => ({ label, spec: Object.assign({ kind: "value", value: r6(v) }, rd ? { round: rd } : {}) })) });
  const gcd = (a, b) => (b ? gcd(b, a % b) : a);

  // ---------- optim : 1re–2e Collège, MP 2e–3e ----------
  const OPT = { co: [12, 13], mp: [13, 14] };
  PX("optim", OPT, () => { /* recette d'un spectacle : prix et fréquentation */
    let p0, n0, k, x; do { p0 = pk([20, 24, 30]); n0 = pk([300, 360, 420, 480, 540]); k = pk([5, 6, 8, 10, 12]); x = (n0 - k * p0) / (2 * k); } while (!(x >= 2 && Number.isInteger(x * 2)));
    const P = p0 + x, n = n0 - k * x, Rm = r6(P * n);
    return PB("Un théâtre vend " + X(n0) + " billets par soir au prix de " + p0 + " CHF. Une étude montre que chaque franc d'augmentation du prix fait perdre " + k + " spectateurs (et chaque franc de baisse en fait gagner autant). On note " + M("x") + " l'augmentation du prix en CHF.",
      [["a) Augmentation " + M("x") + " qui rend la recette maximale, en CHF", x], ["b) Prix du billet correspondant, en CHF", P], ["c) Recette maximale, en CHF", Rm]],
      ["Recette : " + M("R(x) = (" + p0 + " + x)(" + n0 + " - " + k + "x)") + ", une fonction du 2e degré.", "Le maximum est au sommet de la parabole, au milieu de ses deux zéros."],
      M("R(x) = (" + p0 + " + x)(" + n0 + " - " + k + "x)") + " s'annule en " + M("x = -" + p0) + " et " + M("x = " + N(n0 / k)) + ". Sommet au milieu : " + M("x = \\frac{-" + p0 + " + " + N(n0 / k) + "}{2} = " + N(x)) + ". b) " + M(p0 + " + " + N(x) + " = " + N(P)) + " CHF. c) " + M(N(P) + " \\cdot " + N(n) + " = " + N(Rm)) + " CHF (" + N(n) + " spectateurs).");
  });
  PX("optim", OPT, () => { /* ballon : hauteur h(t) = −5t² + vt + h0 */
    const v = pk([12, 14, 16, 18, 22, 24]), h0 = pk([2, 3, 5]), tm = v / 10, hm = r6(h0 + (v * v) / 20), tg = (v + Math.sqrt(v * v + 20 * h0)) / 10;
    return PB("Un ballon est lancé vers le haut. Sa hauteur (en m) après " + M("t") + " secondes est " + M("h(t) = -5t^2 + " + v + "t + " + h0) + ".",
      [["a) Après combien de secondes atteint-il sa hauteur maximale ?", tm], ["b) Hauteur maximale, en m", hm], ["c) Après combien de secondes touche-t-il le sol ? (au centième)", tg, 0.01]],
      ["Sommet d'une parabole " + M("at^2 + bt + c") + " : " + M("t = -\\frac{b}{2a}") + ".", "c) Résous " + M("h(t) = 0") + " et garde la solution positive."],
      "a) " + M("t = -\\frac{" + v + "}{2 \\cdot (-5)} = " + N(tm)) + " s. b) " + M("h(" + N(tm) + ") = " + N(hm)) + " m. c) " + M("\\Delta = " + v * v + " + 20 \\cdot " + h0 + " = " + (v * v + 20 * h0)) + " ; " + M("t = \\frac{" + v + " + \\sqrt{" + (v * v + 20 * h0) + "}}{10} \\approx " + N(Math.round(tg * 100) / 100)) + " s.");
  });
  PX("optim", OPT, () => { /* rectangle sous une droite */
    const a = pk([8, 10, 12, 14]), b = pk([6, 9, 12, 15]);
    return PB("Un rectangle a un sommet en " + M("O(0\\,;\\,0)") + ", deux côtés sur les axes, et le sommet opposé " + M("P(x\\,;\\,y)") + " sur la droite qui passe par " + M("(" + a + "\\,;\\,0)") + " et " + M("(0\\,;\\," + b + ")") + ".",
      [["a) Abscisse de " + M("P") + " pour que l'aire du rectangle soit maximale", a / 2], ["b) Ordonnée de " + M("P") + " correspondante", b / 2], ["c) Aire maximale", (a * b) / 4]],
      ["Équation de la droite : " + M("y = " + b + " - \\frac{" + b + "}{" + a + "}x") + ". L'aire vaut " + M("A(x) = x \\cdot y") + ".", "A(x) est une fonction du 2e degré : son maximum est au sommet, au milieu de ses zéros."],
      M("A(x) = x\\left(" + b + " - \\frac{" + b + "}{" + a + "}x\\right)") + " s'annule en 0 et en " + a + " : sommet en " + M("x = " + N(a / 2)) + ". b) " + M("y = " + b + " - \\frac{" + b + "}{" + a + "} \\cdot " + N(a / 2) + " = " + N(b / 2)) + ". c) " + M(N(a / 2) + " \\cdot " + N(b / 2) + " = " + N((a * b) / 4)) + " (le quart du triangle formé avec les axes, doublé).");
  });

  // ---------- arith : 1re Collège, MP 1re ----------
  PX("arith", { co: [12], mp: [12] }, () => {
    let g, m, n; do { g = ri(12, 48); m = ri(5, 17); n = ri(5, 17); } while (gcd(m, n) !== 1 || m === n);
    const a = g * Math.max(m, n), b = g * Math.min(m, n), L = (a * b) / g;
    return PB("On veut carreler sans découpe une salle rectangulaire de " + X(a) + " cm sur " + X(b) + " cm avec des carreaux carrés identiques, les plus grands possible. On empile ensuite des boîtes de " + X(a) + " mm et de " + X(b) + " mm de haut en deux colonnes séparées.",
      [["a) Côté des carreaux, en cm (algorithme d'Euclide conseillé)", g], ["b) Nombre de carreaux", m * n], ["c) Plus petite hauteur non nulle où les deux colonnes ont la même hauteur, en mm", L]],
      ["Euclide : PGDC(a ; b) = PGDC(b ; reste de a ÷ b), jusqu'au reste nul.", "c) Hauteur commune : multiple commun ; PGDC · PPMC = a · b."],
      "a) PGDC(" + a + " ; " + b + ") = " + g + " cm. b) " + M((a / g) + " \\cdot " + (b / g) + " = " + m * n) + " carreaux. c) PPMC = " + M("\\frac{" + N(a) + " \\cdot " + N(b) + "}{" + g + "} = " + N(L)) + " mm.");
  });
  // ---------- fracper : 1re Collège ----------
  PX("fracper", { co: [12] }, () => {
    let a, per; do { a = ri(1, 9); per = ri(101, 998); } while (per % 111 === 0);
    const num0 = a * 999 + per, den0 = 9990, g = gcd(num0, den0), P = String(per).padStart(3, "0");
    return PB("On considère " + M("x = 0{,}" + a + "\\overline{" + P + "}") + " (le groupe " + P + " se répète indéfiniment).",
      [["a) Que vaut " + M("10\\,000x - 10x") + " ?", num0], ["b) Numérateur de " + M("x") + " sous forme irréductible", num0 / g], ["c) Dénominateur", den0 / g]],
      ["Multiplie par 10 pour placer la période juste après la virgule, puis par 10'000 pour la décaler d'une période entière.", "Simplifie par le PGDC du numérateur et de 9'990."],
      M("10\\,000x = " + a + P + "{,}\\overline{" + P + "}") + ", " + M("10x = " + a + "{,}\\overline{" + P + "}") + " ; " + M("9\\,990x = " + N(num0)) + " ; " + M("x = \\frac{" + N(num0) + "}{9\\,990} = \\frac{" + N(num0 / g) + "}{" + N(den0 / g) + "}") + " (PGDC " + g + ").");
  });
  // ---------- premiers : MP 1re ----------
  PX("premiers", { mp: [12] }, () => {
    const a = ri(2, 5), b = ri(1, 4), c = ri(1, 2), n = 2 ** a * 3 ** b * 5 ** c, cube = 2 ** ((3 - (a % 3)) % 3) * 3 ** ((3 - (b % 3)) % 3) * 5 ** ((3 - (c % 3)) % 3);
    const m = 2 ** pk([1, 2]) * 3 ** pk([2, 3]) * 7, g = gcd(n, m);
    return PB("On considère " + M("n = " + N(n)) + " et " + M("m = " + N(m)) + ".",
      [["a) Nombre de diviseurs de " + M("n"), (a + 1) * (b + 1) * (c + 1)], ["b) Plus petit entier " + M("k") + " tel que " + M("n \\cdot k") + " soit un cube parfait", cube], ["c) PGDC(" + M("n") + " ; " + M("m") + ")", g]],
      ["Décompose n en facteurs premiers. Un diviseur choisit un exposant pour chaque facteur premier, de 0 au maximum.", "Un cube : chaque exposant est un multiple de 3. PGDC : facteurs communs, avec le plus petit exposant."],
      M("n = 2^{" + a + "} \\cdot 3^{" + b + "} \\cdot 5^{" + c + "}") + ". a) " + M("(" + (a + 1) + ")(" + (b + 1) + ")(" + (c + 1) + ") = " + (a + 1) * (b + 1) * (c + 1)) + ". b) Exposants à compléter jusqu'au multiple de 3 suivant : " + M("k = " + N(cube)) + ". c) " + M("m = " + m.toString()) + " ; PGDC " + M("= " + g) + ".");
  });
  // ---------- rac : MP 1re ----------
  PX("rac", { mp: [12] }, () => {
    let p, m, q, nn; do { p = pk([2, 3, 4, 5, 6]); m = pk([2, 3, 5, 6, 7]); q = pk([3, 5, 7, 11]); nn = pk([2, 3, 5]); } while (q === m || nn === m || q * q === m);
    const A = p * p * m, prod = 4 * m - nn, bb = pk([[7, 5], [11, 7], [13, 11], [10, 6], [8, 6]]);
    return PB("Calcul avec des racines carrées (sans calculatrice).",
      [["a) " + M("\\sqrt{" + A + "}") + " s'écrit " + M("a\\sqrt{" + m + "}") + " : que vaut " + M("a") + " ?", p], ["b) " + M("(2\\sqrt{" + m + "} + \\sqrt{" + nn + "})(2\\sqrt{" + m + "} - \\sqrt{" + nn + "})") + " = ?", prod], ["c) " + M("\\frac{1}{\\sqrt{" + bb[0] + "} - \\sqrt{" + bb[1] + "}} = \\frac{\\sqrt{" + bb[0] + "} + \\sqrt{" + bb[1] + "}}{d}") + " : que vaut " + M("d") + " ?", bb[0] - bb[1]]],
      ["a) Cherche le plus grand carré qui divise " + A + ".", "b) Identité (u + v)(u − v) = u² − v². c) Multiplie haut et bas par la quantité conjuguée."],
      "a) " + M("\\sqrt{" + A + "} = \\sqrt{" + p * p + " \\cdot " + m + "} = " + p + "\\sqrt{" + m + "}") + ". b) " + M("(2\\sqrt{" + m + "})^2 - (\\sqrt{" + nn + "})^2 = " + 4 * m + " - " + nn + " = " + prod) + ". c) " + M("(\\sqrt{" + bb[0] + "} - \\sqrt{" + bb[1] + "})(\\sqrt{" + bb[0] + "} + \\sqrt{" + bb[1] + "}) = " + bb[0] + " - " + bb[1] + " = " + (bb[0] - bb[1])) + ".");
  });
})();

