// Chapitre du sujet de préparation : celui dont la banque couvre le plus de notions révisées (au moins la moitié).
// 23.11 : une banque peut être réservée à une filière (track: "mp" = maturité professionnelle, "col" = Collège) ;
// à couverture égale, la banque de la filière de l'élève passe devant (mêmes notions, niveaux très différents).
function richChapter(ids, profile) {
  if (profile === undefined) profile = typeof state !== "undefined" && state && state.profile;
  const tr = profile && profile.track === "mp" && profile.grade >= 12 ? "mp" : profile && profile.grade >= 12 ? "col" : null;
  let best = null, n = 0;
  for (const [k, c] of Object.entries(RICH)) {
    if ((c.track === "mp" && tr !== "mp") || (c.track === "col" && tr === "mp")) continue;
    const m = ids.filter((id) => c.ids.includes(id)).length + (c.track && c.track === tr ? 0.5 : 0);
    if (m > n) { best = k; n = m; }
  }
  return best && Math.floor(n) * 2 >= ids.length ? best : null;
}

// Secondaire II (23.11) : outils communs aux banques riches riche_mp2.js, riche_mp1.js, riche_2c.js, et banques de la
// MP 2e (fonctions du premier degré, trigonométrie, analyse de données). Niveau calé sur les épreuves et les
// polycopiés CFPT MP2 (base Maurizio) : beaucoup plus simple que le Collège, calculatrice autorisée.
// Format des exercices : voir riche.js. En plus, chk : [[valeur calculée indépendamment, valeur affichée, tolérance?], …]
// sert au test tests/riche2.html (la valeur affichée dans le corrigé est relue par checkAnswer).
const RX = (() => {
  const r6 = (v) => Math.round(v * 1e6) / 1e6;
  const N = (v) => { let [i, f] = String(r6(v)).split("."); if (i.replace("-", "").length >= 4) i = i.replace(/\B(?=(\d{3})+(?!\d))/g, "\\text{'}"); return i + (f ? "{,}" + f : ""); };
  const A = (v, k) => N(+(+v).toFixed(k));
  const u = (s) => ("\\ \\text{" + s.replace(/\^([23])/, "}^$1\\text{") + "}").replace(/\\text\{\}$/, "");
  const Q = (v, s) => M(N(v) + u(s));
  const pk = (a) => a[Math.floor(R.rand() * a.length)];
  const g2 = (a, b) => (b ? g2(b, a % b) : Math.abs(a));
  // Nombre exact : entier, fraction (dénominateur ≤ 12) ou décimal.
  const FR = (v) => {
    if (Math.abs(v - Math.round(v)) < 1e-9) return N(Math.round(v));
    for (let d = 2; d <= 12; d++) { const n = Math.round(v * d); if (Math.abs(n / d - v) < 1e-9) { const g = g2(n, d); return (n < 0 ? "-" : "") + "\\frac{" + Math.abs(n) / g + "}{" + d / g + "}"; } }
    return N(v);
  };
  // a·x + b écrit proprement (a, b exacts).
  const lin = (a, b, x = "x") => {
    const c = Math.abs(a - 1) < 1e-9 ? x : Math.abs(a + 1) < 1e-9 ? "-" + x : FR(a) + x;
    if (Math.abs(a) < 1e-9) return FR(b);
    return c + (Math.abs(b) < 1e-9 ? "" : b < 0 ? " - " + FR(-b) : " + " + FR(b));
  };
  const cx = (a, x = "x") => (Math.abs(a - 1) < 1e-9 ? x : Math.abs(a + 1) < 1e-9 ? "-" + x : FR(a) + x); // coefficient · x
  const sg = (v) => (v < 0 ? " - " + FR(-v) : " + " + FR(v)); // « + 3 » ou « - 3 »
  const par = (v) => (v < 0 ? "(" + FR(v) + ")" : FR(v));
  const pd = (t) => colonBreak(String(t).split(/(\\\(.*?\\\))/).map((seg, i) => (i % 2 ? seg : seg.replace(/\{,\}/g, ",").replace(/\\text\{'\}/g, "'"))).join(""));
  const X = (o) => Object.assign({ pts: Math.max(1, o.parts.reduce((s, p) => s + p.pts, 0)), chk: [] }, o, { q: pd(o.q), sol: pd(o.sol), parts: o.parts.map((p) => ({ label: pd(p.label), pts: p.pts })) });
  const ul = (rows) => "<ol type=\"a\" class=\"mock-parts\">" + rows.map((r) => "<li>" + r + "</li>").join("") + "</ol>";
  const who = () => pk(["Lina", "Noé", "Inès", "Yanis", "Mia", "Sam", "Elsa", "Luca"]);
  const shuffle = (a) => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(R.rand() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const tab = (head, rows) => "<table class=\"mtab\"><tr>" + head.map((h) => "<th>" + h + "</th>").join("") + "</tr>" + rows.map((r) => "<tr>" + r.map((c) => "<td>" + c + "</td>").join("") + "</tr>").join("") + "</table>";
  // Vrai ou faux : n affirmations tirées d'une liste [texte, vrai?, justification].
  const VF = (id, lv, L, n = 4) => { const S = shuffle(L).slice(0, n);
    return X({ id, lv, titre: "Vrai ou faux ? Justifie", q: "Pour chaque affirmation, dis si elle est vraie ou fausse, et justifie (calcul, exemple ou contre-exemple).",
      parts: S.map((s) => ({ label: s[0], pts: 1 })), sol: ul(S.map((s) => "<b>" + (s[1] ? "Vrai" : "Faux") + "</b>. " + s[2])) }); };
  const D = Math.PI / 180;
  return { r6, N, A, u, Q, pk, g2, FR, lin, cx, sg, par, pd, X, ul, who, shuffle, tab, VF, D };
})();

