  bicarre: () => FIG.plot([{ f: (x) => x ** 4 - 5 * x * x + 4 }], [[-2, 0, ""], [-1, 0, ""], [1, 0, ""], [2, 0, ""]], { numbers: true, xr: [-3, 3], yr: [-3, 6], squash: 0.6 }),
