  modexp: () => FIG.plot([{ f: (t) => 2 ** (t / 3) }], [[3, 2, ""], [6, 4, ""], [9, 8, ""]], { numbers: true, xr: [-1, 10], yr: [-1, 9], squash: 0.6 }),
