  homogrec: () => FIG.plot([{ f: (x) => (Math.abs(x - 3) > 0.02 ? (2 * x + 1) / (x - 3) : NaN) }, { f: (x) => (Math.abs(x - 2) > 0.02 ? (3 * x + 1) / (x - 2) : NaN), cls: "f-line" }, { f: (x) => x, dash: true, cls: "f-line" }], [], { numbers: true, step: 2, xr: [-6, 10], yr: [-6, 10], squash: 0.6 }),
