  pythrec: () => GF.rightTri(3, 4, { la: "a", lb: "b", lc: "c" }),
  airepyr: () => FIG.pyramid("c", "h"),
  volcomp: () => GF.profile("cone", 6, 5, 3, { r: "r", h1: "h", h2: "h'" }),
